  if (cache.inFlight) {
    return cache.inFlight;
  }
  const pending = (async () => {
    const result = await resolveStudioNewReviewPreflight({ repoRoot });
    cache = {
      headSha: resolveHeadSha(repoRoot),
      policyMode: resolveStudioPolicyMode(repoRoot),
      value: result,
      inFlight: null,
