    const output = execFileSync('git', ['rev-parse', '--git-dir'], {
      cwd: repoRoot,
      encoding: 'utf8',
      stdio: ['ignore', 'pipe', 'ignore'],
    })
      .toString()
      .trim();
    if (!output) {
      return null;
    }
    return output.startsWith('/') ? output : join(repoRoot, output);
  } catch {
    return null;
  }
